/* Override the synthesized chime with the real ringtone MP3 */
(function patchAdminRingtone(){
  var _playing = false;
  var _interval = null;

  function playOnce(){
    var a = document.getElementById('__zomato_ring__');
    if(!a) return;
    try{ a.currentTime = 0; var p = a.play(); if(p && p.catch) p.catch(function(){}); }catch(e){}
  }

  function doPlay(){
    if(_playing) return;
    _playing = true;
    playOnce();
    _interval = setInterval(playOnce, 2400);
  }

  function doStop(){
    _playing = false;
    if(_interval){ clearInterval(_interval); _interval = null; }
    var a = document.getElementById('__zomato_ring__');
    if(a){ try{ a.pause(); a.currentTime = 0; }catch(e){} }
  }

  /* Patch after the obfuscated script finishes (it runs at DOMContentLoaded) */
  function patch(){
    window.playZomatoRingtone  = doPlay;
    window.stopZomatoRingtone  = doStop;
    window._ringtonePlaying    = false; // keep obfuscated flag in sync
  }

  /* Try immediately, then again after scripts settle */
  patch();
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(patch, 100); });
  } else {
    setTimeout(patch, 100);
  }
})();
/* ── DELIVERY SETTINGS VARIABLES ── */
let _dsSettings = {
  enabled: false,
  fee: 0,
  freeAbove: 0
};

function updateDsPreview() {
  const enabled =
    document.getElementById('ds-enabled-toggle')?.checked || false;

  const fee =
    Number(document.getElementById('ds-fee-amount')?.value) || 0;

  const freeAbove =
    Number(document.getElementById('ds-free-above')?.value) || 0;

  const previewEl =
    document.getElementById('ds-preview-fee');

  const subEl =
    document.getElementById('ds-preview-sub');

  if (!enabled) {

    if (previewEl) {
      previewEl.textContent = '🎁 Free Delivery';
    }

    if (subEl) {
      subEl.innerHTML = 'Delivery is currently <strong>free</strong>';
    }

    return;
  }

  if (freeAbove > 0) {

    if (previewEl) {
      previewEl.textContent =
        '₹' + fee + ' (free above ₹' + freeAbove + ')';
    }

  } else {

    if (previewEl) {
      previewEl.textContent =
        '₹' + fee + ' delivery fee';
    }
  }
}

function onDsToggleChange() {

  const enabled =
    document.getElementById('ds-enabled-toggle').checked;

  const feeIn =
    document.getElementById('ds-fee-amount');

  const freeIn =
    document.getElementById('ds-free-above');

  if (feeIn) feeIn.disabled = !enabled;

  if (freeIn) freeIn.disabled = !enabled;

  updateDsPreview();
}

async function saveDsSettings() {

  const enabled =
    document.getElementById('ds-enabled-toggle').checked;

  const fee =
    Number(document.getElementById('ds-fee-amount').value) || 0;

  const freeAbove =
    Number(document.getElementById('ds-free-above').value) || 0;

  await db.collection('settings')
    .doc('deliverySettings')
    .set({
      enabled,
      fee,
      freeAbove,
      updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    }, { merge: true });

  showToast('✅ Delivery settings saved');
}

function applyDsToAdminPage() {

  const tog =
    document.getElementById('ds-enabled-toggle');

  const feeI =
    document.getElementById('ds-fee-amount');

  const freeI =
    document.getElementById('ds-free-above');

  if (!tog) return;

  tog.checked = _dsSettings.enabled;

  if (feeI) feeI.value = _dsSettings.fee;

  if (freeI) freeI.value = _dsSettings.freeAbove;

  if (feeI) feeI.disabled = !_dsSettings.enabled;

  if (freeI) freeI.disabled = !_dsSettings.enabled;

  updateDsPreview();
}

function startDeliverySettingsListener() {

  db.collection('settings')
    .doc('deliverySettings')
    .onSnapshot((snap) => {

      if (snap.exists) {

        const data = snap.data();

        _dsSettings = {
          enabled: data.enabled || false,
          fee: data.fee || 0,
          freeAbove: data.freeAbove || 0
        };

        if (typeof applyDsToAdminPage === 'function') {
          applyDsToAdminPage();
        }

        updateCartDeliveryFee();
      }
    });
}

document.addEventListener('DOMContentLoaded', () => {

  const waitForDb = setInterval(() => {

    if (typeof db !== 'undefined' && db) {

      clearInterval(waitForDb);

      startDeliverySettingsListener();
    }

  }, 400);

});
