(function supportTicketBadge() {
  'use strict';

  var _unsub       = null;
  var _openCount   = 0;
  var _seenCount   = parseInt(localStorage.getItem('_sbSeen') || '0', 10);

  /* ── Show / hide badge ── */
  function setBadge(n) {
    var el = document.getElementById('asb-support-badge');
    if (!el) return;
    var unseen = Math.max(0, n - _seenCount);
    if (unseen > 0) {
      el.textContent = unseen > 99 ? '99+' : String(unseen);
      el.style.cssText = 'display:inline-block;background:#e53935;color:#fff;border-radius:50px;padding:2px 7px;font-size:.62rem;font-weight:900;min-width:18px;text-align:center;animation:sbPop .35s cubic-bezier(.34,1.56,.64,1)';
    } else {
      el.style.display = 'none';
    }
  }

  /* ── Start Firestore listener — retries until db is ready ── */
  function startListener() {
    if (_unsub) return;
    if (typeof db === 'undefined' || !db) { setTimeout(startListener, 700); return; }
    console.log('[SupportBadge] Starting listener...');
    try {
      _unsub = db.collection('support')
        .where('status', '==', 'open')
        .onSnapshot(function(snap) {
          _openCount = snap ? snap.size : 0;
          console.log('[SupportBadge] Open:', _openCount, '| Seen:', _seenCount);
          setBadge(_openCount);
        }, function(err) {
          console.warn('[SupportBadge] Error:', err.code, err.message);
        });
    } catch (e) {
      console.warn('[SupportBadge] threw:', e);
    }
  }

  /* ── Mark all as "seen" when admin opens support page ── */
  function markSeen() {
    _seenCount = _openCount;
    localStorage.setItem('_sbSeen', String(_seenCount));
    setBadge(_openCount);
    console.log('[SupportBadge] Marked', _seenCount, 'as seen');
  }

  /* ── Hook the sidebar button directly ── */
  function hookButton() {
    var btn = document.getElementById('asb-support');
    if (!btn) { setTimeout(hookButton, 400); return; }
    btn.addEventListener('click', function() { setTimeout(markSeen, 350); });
    console.log('[SupportBadge] Button hooked');
  }

  /* ── Also hook adminSidebarGo for programmatic navigation ── */
  function hookSidebarGo() {
    var orig = window.adminSidebarGo;
    if (typeof orig !== 'function') { setTimeout(hookSidebarGo, 400); return; }
    window.adminSidebarGo = function(page) {
      orig.apply(this, arguments);
      if (page === 'admin-support') setTimeout(markSeen, 350);
    };
    console.log('[SupportBadge] adminSidebarGo hooked');
  }

  /* ── CSS for pop animation ── */
  function injectCSS() {
    if (document.getElementById('_sb_css')) return;
    var s = document.createElement('style');
    s.id = '_sb_css';
    s.textContent = '@keyframes sbPop{from{transform:scale(.4);opacity:0}to{transform:scale(1);opacity:1}}';
    document.head.appendChild(s);
  }

  function init() {
    injectCSS();
    hookButton();
    hookSidebarGo();
    startListener();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    setTimeout(init, 300);
  }
})();

